import { useState } from 'react';
import { normalizeHeadword, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Button } from '@/components/ui/Button.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { useTextLimits } from '@/lib/useConfig.js';
import { importWords, type ImportRow } from '@/db/mutations.js';
import { listWords } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { syncSoon } from '@/sync/store.js';
import { notePasteUse } from '@/features/everywhere/state.js';
import { listNotebooks } from '@/db/repo.js';
import type { StoredNotebook } from '@/db/schema.js';
import { NewNotebookSheet } from './NewNotebookSheet.js';
import { NotebookRoute } from './NotebookRoute.js';
import { routeFor, settles } from './route.js';
import { wordsInText, type Candidate } from './pick.js';
import styles from './PasteSheet.module.css';
import { trackWords } from '@/features/celebrate/state.js';

/**
 * Paste something you read, and pick the words you did not know.
 *
 * Adding words one at a time is the slowest thing in Lexpad, and the words
 * worth adding almost always arrive together — a page, an article, a
 * message. This shortens that walk without taking the choice away: the
 * text is split into words, the ones already in the notebook are set
 * aside, and every remaining word waits to be tapped. Nothing is
 * pre-selected, because a list somebody accepted is not a list they chose.
 *
 * The words arrive bare. An example illustrates a meaning and these have
 * none yet, so there is nowhere honest to keep the sentence they were met
 * in; the meaning comes next, by hand or from the AI.
 */
export function PasteSheet({
  notebookId,
  targetLang,
  onClose,
}: {
  notebookId: string;
  targetLang: LanguageCode;
  onClose: () => void;
}): React.JSX.Element {
  const limits = useTextLimits();
  const [text, setText] = useState('');
  const [found, setFound] = useState<ReturnType<typeof wordsInText> | undefined>();
  const [chosen, setChosen] = useState<ReadonlySet<string>>(new Set());
  const [busy, setBusy] = useState(false);
  // Where these words go. A text is much easier to read than a single word,
  // so the script almost always settles it outright.
  const [picked, setPicked] = useState<StoredNotebook | undefined>();
  const [making, setMaking] = useState<{ language: LanguageCode | undefined } | undefined>();

  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);
  const all = notebooks ?? [];
  const here = all.find((notebook) => notebook.id === notebookId);
  const destination = routeFor(text, all, here);
  const into = picked ?? settles(destination, here) ?? here;
  const writingTo = into?.id ?? notebookId;

  const existing = useLiveQuery(
    async () => new Set((await listWords(writingTo)).map((word) => normalizeHeadword(word.headword))),
    undefined,
    [writingTo],
  );

  const ready = existing !== undefined;

  const look = (): void => {
    if (!ready) return;
    setFound(wordsInText(text, existing, limits.paste));
    setChosen(new Set());
  };

  const toggle = (word: string): void => {
    setChosen((previous) => {
      const next = new Set(previous);
      if (next.has(word)) next.delete(word);
      else next.add(word);
      return next;
    });
  };

  const keep = (candidates: readonly Candidate[]): void => {
    const rows: ImportRow[] = candidates
      .filter((candidate) => chosen.has(candidate.word))
      .map((candidate) => ({
        ref: candidate.word,
        word: {
          headword: candidate.word,
          category: 'general',
          source: 'manual',
          // No meanings at all, rather than an empty one holding the
          // sentence: an example illustrates a meaning, so a card cannot
          // carry one before it has a meaning to illustrate. The word
          // arrives bare and is filled in by hand or by the AI.
          meanings: [],
          expressions: [],
          collocations: [],
          relatedWords: [],
          relatedWordIds: [],
        },
        relatedRefs: [],
      }));
    if (rows.length === 0) return;
    setBusy(true);
    void trackWords(() => importWords(writingTo, rows, localTimeZone()))
      .then(() => notePasteUse())
      .then(() => syncSoon())
      .then(onClose)
      .catch(() => {
        setBusy(false);
      });
  };

  if (making !== undefined) {
    return (
      <NewNotebookSheet
        {...(making.language === undefined ? {} : { startAt: making.language })}
        onCreated={(made) => {
          setMaking(undefined);
          const fresh = all.find((notebook) => notebook.id === made);
          if (fresh !== undefined) setPicked(fresh);
        }}
        onClose={() => {
          setMaking(undefined);
        }}
      />
    );
  }

  return (
    <Sheet title={t('paste.title')} onClose={onClose}>
      <div className={styles.body}>
        {found === undefined ? (
          <>
            <p className={styles.lead}>{t('paste.lead')}</p>
            <textarea
              className={styles.input}
              value={text}
              dir="auto"
              rows={8}
              placeholder={t('paste.placeholder')}
              aria-label={t('paste.placeholder')}
              autoFocus
              onChange={(event) => {
                setText(event.target.value);
              }}
            />
            <NotebookRoute
              destination={destination}
              chosen={into}
              onChoose={setPicked}
              onMake={(language) => {
                setMaking({ language });
              }}
            />
            <Button
              block
              disabled={!ready || text.trim() === '' || destination.kind === 'missing'}
              onClick={look}
            >
              {t('paste.find')}
            </Button>
          </>
        ) : found.candidates.length === 0 ? (
          <>
            <p className={styles.lead}>{found.alreadyHave > 0 ? t('paste.allKnown') : t('paste.noWords')}</p>
            <Button
              variant="secondary"
              block
              onClick={() => {
                setFound(undefined);
              }}
            >
              {t('paste.again')}
            </Button>
          </>
        ) : (
          <>
            <p className={styles.lead}>{t('paste.pick')}</p>
            {/* Chinese and Japanese need a dictionary to be broken into
                words, and not every phone's browser engine carries one.
                Where it is missing these are single characters: real units,
                but not the words of the text, and saying so is the
                difference between a limitation and a wrong answer. */}
            {found.byCharacter && <p className={styles.note}>{t('paste.byCharacter')}</p>}
            <div className={styles.words} role="group" aria-label={t('paste.pick')}>
              {found.candidates.map((candidate) => {
                const on = chosen.has(candidate.word);
                return (
                  <button
                    key={candidate.word}
                    type="button"
                    className={cx(styles.word, on && styles.wordOn)}
                    aria-pressed={on}
                    onClick={() => {
                      toggle(candidate.word);
                    }}
                  >
                    <Bilingual lang={into?.targetLang ?? targetLang}>{candidate.word}</Bilingual>
                  </button>
                );
              })}
            </div>
            <p className={styles.note}>
              {found.alreadyHave > 0 &&
                (found.alreadyHave === 1
                  ? t('paste.haveOne')
                  : t('paste.have', { count: found.alreadyHave }))}
              {found.truncated && ` ${t('paste.truncated')}`}
            </p>
          </>
        )}
      </div>

      {found !== undefined && found.candidates.length > 0 && (
        <div className={styles.foot}>
          <Button
            block
            size="large"
            busy={busy}
            disabled={chosen.size === 0}
            onClick={() => {
              keep(found.candidates);
            }}
          >
            {chosen.size === 0
              ? t('paste.none')
              : chosen.size === 1
                ? t('paste.addOne')
                : t('paste.add', { count: chosen.size })}
          </Button>
        </div>
      )}
    </Sheet>
  );
}
